uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float lengthPx;
uniform float angle;
uniform float intensity;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float4 c=readInput((coord / size)),b=float4(0.0);float2 d=float2(cos(angle*.0174532925),sin(angle*.0174532925))*lengthPx;for(int i=-8;i<=8;i++)b+=readInput((coord / size)+d*float(i)/8.0)/17.0;float a=clamp(c.a+b.a*intensity,0.0,1.0);return float4(min(c.rgb+b.rgb*intensity,float3(a)),a);}
